/** A look's card shows three examples on the Illustrated Explainer, joined in one video, and a still from
 * each. The prepared input is the same graphic in every look. Rendered by the looks' own code. */
function lookVisual(id:string,summary:string,examples:string[]):RecipeVisual{
 const root=`/recipe-previews/look-${id}/`;
 return {
  video:root+'result.mp4',poster:root+'poster.jpg',summary,
  credit:'Built in DreamCut as an editable code-built motion graphic; no footage, generated imagery or people.',
  note:'Three examples at normal speed, each with its own words and scenes.',
  inputs:[{words:examples,label:'Your words and scenes',role:'supply'},{file:'/recipe-previews/look-inputs/all-looks.jpg',label:'Same graphic, every look',role:'prepared'}],
  stages:examples.map((name,i)=>({file:`${root}example-${i+1}.jpg`,label:`${i+1} · ${name}`})),
 };
}
